CREATE TYPE fact_status AS ENUM ('draft','pending_review','approved','rejected','superseded','withdrawn');
CREATE TYPE risk_level AS ENUM ('low','medium','high','critical');
CREATE TYPE fact_value_type AS ENUM ('date','datetime','money','integer','decimal','text','boolean','json');
CREATE TYPE event_type AS ENUM ('application_open','application_deadline','exam_date','result_date','fee_change','eligibility_change','schedule_change','system_change');
CREATE TABLE qualifications (id text PRIMARY KEY, slug text NOT NULL UNIQUE, official_name_ja text NOT NULL, aliases_ja jsonb NOT NULL, field text NOT NULL, category text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE institutions (id text PRIMARY KEY, name_ja text NOT NULL, official boolean NOT NULL DEFAULT true);
CREATE TABLE sources (id text PRIMARY KEY, institution_id text NOT NULL REFERENCES institutions(id), canonical_url text NOT NULL UNIQUE, allowed_domain text NOT NULL, source_type text NOT NULL, active boolean NOT NULL DEFAULT true);
CREATE TABLE snapshots (id text PRIMARY KEY, source_id text NOT NULL REFERENCES sources(id), content_hash text NOT NULL, object_key text NOT NULL, synthetic boolean NOT NULL DEFAULT false, retrieved_at timestamptz NOT NULL, UNIQUE(source_id, content_hash));
CREATE TABLE candidate_facts (id text PRIMARY KEY, qualification_id text NOT NULL REFERENCES qualifications(id), exam_level_id text, exam_year integer NOT NULL, fact_key text NOT NULL, value_type fact_value_type NOT NULL, normalized_value jsonb NOT NULL, display_value text NOT NULL, status fact_status NOT NULL DEFAULT 'pending_review', risk_level risk_level NOT NULL, source_id text NOT NULL REFERENCES sources(id), source_snapshot_id text NOT NULL REFERENCES snapshots(id), synthetic boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source_snapshot_id, qualification_id, exam_level_id, exam_year, fact_key));
CREATE TABLE fact_revisions (id text PRIMARY KEY, candidate_fact_id text NOT NULL REFERENCES candidate_facts(id), status fact_status NOT NULL, normalized_value jsonb NOT NULL, display_value text NOT NULL, valid_from timestamptz NOT NULL, valid_to timestamptz, verified_at timestamptz NOT NULL, idempotency_key text NOT NULL UNIQUE);
CREATE TABLE facts (id text PRIMARY KEY, qualification_id text NOT NULL REFERENCES qualifications(id), exam_level_id text, exam_year integer NOT NULL, fact_key text NOT NULL, current_revision_id text REFERENCES fact_revisions(id), status fact_status NOT NULL DEFAULT 'draft', UNIQUE(qualification_id, exam_level_id, exam_year, fact_key));
CREATE TABLE reviews (id text PRIMARY KEY, candidate_fact_id text NOT NULL REFERENCES candidate_facts(id), decision text NOT NULL, reviewer_id text NOT NULL, reason text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE conflicts (id text PRIMARY KEY, candidate_fact_id text NOT NULL REFERENCES candidate_facts(id), other_source_id text NOT NULL REFERENCES sources(id), status text NOT NULL DEFAULT 'open', details jsonb NOT NULL);
CREATE TABLE change_events (id text PRIMARY KEY, fact_id text NOT NULL REFERENCES facts(id), event_type event_type NOT NULL, previous_revision_id text, new_revision_id text NOT NULL, affected_pages jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
